"[data-pk-all]\");\n    if(t.closest(\"[data-pk-cyc]\")){\n      setTimeout(function(){[].forEach.call(document.querySelectorAll(\".pk-vol\"),function(d){if(d.open&&!d.hasAttribute(\"data-rp\")&&!exclu(d)){var k=cle(d);if(k)d.setAttribute(\"data-rp\",k);}});},0);\n      return;\n    }\n    if(s&&s.parentNode&&s.parentNode.tagName===\"DETAILS\"&&s.parentNode.hasAttribute(\"data-rp\")){\n      var d=s.parentNode;setTimeout(function(){noter(d);sauver();},0);\n    }else if(a){\n      setTimeout(function(){[].forEach.call(document.querySelectorAll(\".pk-vol[data-rp]\"),noter);sauver();},0);\n    }\n  },true);\n  new MutationObserver(function(ms){\n    for(var i=0;i<ms.length;i++){var ad=ms[i].addedNodes;for(var j=0;j<ad.length;j++)balayer(ad[j]);}\n  }).observe(document.documentElement,{childList:true,subtree:true});\n  balayer(document.body||document.documentElement);\n})();</script>\n";
